def norm360(a):
    return a % 360.0


def jd_ut(y, m, d, h):
    if m <= 2:
        y -= 1
        m += 12
    A = y // 100
    B = 2 - A + A // 4
    return math.floor(365.25 * (y + 4716)) + math.floor(30.6001 * (m + 1)) + d + B - 1524.5 + h / 24


def gmst_deg(J):
    T = (J - 2451545) / 36525
    return norm360(280.46061837 + 360.98564736629 * (J - 2451545) + 0.000387933 * T * T)


def vec(ra, dec):
    return [math.cos(dec * DEG) * math.cos(ra * DEG), math.cos(dec * DEG) * math.sin(ra * DEG), math.sin(dec * DEG)]


def radec(v):
    n = math.sqrt(sum(x * x for x in v))
    return norm360(math.atan2(v[1], v[0]) / DEG), math.asin(v[2] / n) / DEG


def mv(M, v):
    return [M[i][0] * v[0] + M[i][1] * v[1] + M[i][2] * v[2] for i in range(3)]


def mvT(M, v):
    return [M[0][i] * v[0] + M[1][i] * v[1] + M[2][i] * v[2] for i in range(3)]


def dot(a, b):
    return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]


def unit(v):
    n = math.sqrt(dot(v, v))
    return [x / n for x in v]


def sep(a, b):
    return math.acos(max(-1.0, min(1.0, dot(unit(a), unit(b))))) / DEG


def precession(J):
    T = (J - 2451545) / 36525
    a = DEG / 3600
    z = (2306.2181 * T + 1.09468 * T * T) * a
    ze = (2306.2181 * T + 0.30188 * T * T) * a
    th = (2004.3109 * T - 0.42665 * T * T) * a
    cz, sz, ce, se, ct, st = math.cos(z), math.sin(z), math.cos(ze), math.sin(ze), math.cos(th), math.sin(th)
    return [[cz * ct * ce - sz * se, -cz * ct * se - sz * ce, -cz * st], [sz * ct * ce + cz * se, -sz * ct * se + cz * ce, -sz * st], [st * ce, -st * se, ct]]


EPS = 23.4393 * DEG


def ecl2eq(v):
    return [v[0], v[1] * math.cos(EPS) - v[2] * math.sin(EPS), v[1] * math.sin(EPS) + v[2] * math.cos(EPS)]


