def _palms():
    s, L = 2012, []
    for _ in range(46):
        s = (s * 16807) % 2147483647
        a = s / 2147483647
        s = (s * 16807) % 2147483647
        b = s / 2147483647
        s = (s * 16807) % 2147483647
        c = s / 2147483647
        L.append(((345 + a * 205) % 360, 2.2 + b * 4.2, 0.6 + c * 0.9))
    return L


PALMS = _palms()


def skyline(az):
    az = norm360(az)
    if 186 < az < 334:
        return -0.15
    edge = min(abs((az - 186 + 540) % 360 - 180), abs((az - 334 + 540) % 360 - 180))
    ramp = min(1.0, edge / 8)
    h = (0.9 + 0.5 * math.sin(az * 0.21) + 0.35 * math.sin(az * 0.67 + 1) + 0.2 * math.sin(az * 1.9)) * ramp
    for a, ht, w in PALMS:
        d = abs((az - a + 540) % 360 - 180)
        if d < w * 2.2:
            h = max(h, ramp * (ht if d < 0.12 else ht - 1.1 * (d / w) ** 1.4))
    return h


