def bv_rgb(bv):
    t = max(-0.4, min(2.0, bv))
    if t < 0.4:
        r, g, b = 0.72 + 0.7 * (t + 0.4), 0.8 + 0.4 * (t + 0.4), 1.0
    else:
        r, g, b = 1.0, 1.05 - 0.28 * (t - 0.4), 1 - 0.45 * (t - 0.4)
    return min(1, r), min(1, g), max(0.35, min(1, b))


def hexc(r, g, b):
    return "#%02x%02x%02x" % (int(max(0, min(255, r))), int(max(0, min(255, g))), int(max(0, min(255, b))))


